def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c] != 0]

    # Select the coordinate that stays constant along the colored lines.
    coords = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r - c,
        lambda r, c: r + c,
    ]
    key_fn = min(coords, key=lambda f: len({f(r, c) for r, c, _ in points}))

    constraints = {}
    for r, c, color in points:
        k = key_fn(r, c)
        if k in constraints and constraints[k] != color:
            continue
        constraints[k] = color

    # Find the smallest repeating period consistent with all observed lines.
    period = 1
    for p in range(1, 2 * (h + w) + 2):
        residues = {}
        valid = True
        for k, color in constraints.items():
            rem = k % p
            if rem in residues and residues[rem] != color:
                valid = False
                break
            residues[rem] = color
        if valid:
            period, residues = p, residues
            break

    # If any residue is unobserved, use the closest observed residue.
    observed = list(residues.items())
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            rem = key_fn(r, c) % period
            if rem in residues:
                row.append(residues[rem])
            else:
                nearest = min(observed, key=lambda item: min(
                    (rem - item[0]) % period, (item[0] - rem) % period))
                row.append(nearest[1])
        out.append(row)
    return out
